def search_servers(query, n=None, **_extra):
    import json, os, datetime, time, hashlib, math, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0245000" if __import__("os").path.isdir("./environment_mix/0245000") else "/app/database")

    def _load(nm):
        try:
            with open(os.path.join(_DB, nm), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(nm, d):
        with open(os.path.join(_DB, nm), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- basic validation ---
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    if len(query) < 1 or len(query) > 2000:
        return _err("VALIDATION_ERROR", "query length must be between 1 and 2000")

    if n is None:
        n_req = 3
    else:
        if not isinstance(n, (int, float)) or isinstance(n, bool):
            return _err("VALIDATION_ERROR", "n must be a number")
        if int(n) != n:
            return _err("VALIDATION_ERROR", "n must be an integer between 1 and 5")
        n_req = int(n)

    if n_req < 1 or n_req > 5:
        return _err("VALIDATION_ERROR", "n must be between 1 and 5")

    # --- rate limit / quota (based on request_fingerprint) ---
    # No explicit identity is provided. Use a stable local fingerprint for the day + query.
    day = now[:10]
    fp_raw = f"anonymous|{day}|{query.strip()}"
    request_fingerprint = hashlib.sha256(fp_raw.encode("utf-8")).hexdigest()

    searches = _load("search_queries.json")

    # daily quota: 200 searches per fingerprint/day
    # per-minute rate limit: 30 searches per fingerprint/minute
    daily_quota = 200
    per_minute = 30

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            # expects ...Z
            if ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    now_dt = _parse_ts(now)
    used_today = 0
    used_minute = 0
    if now_dt is not None:
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        for r in searches:
            if r.get("request_fingerprint") != request_fingerprint:
                continue
            cdt = _parse_ts(r.get("created_at"))
            if cdt is None:
                continue
            if cdt.date() == now_dt.date():
                used_today += 1
            if cdt >= minute_ago:
                used_minute += 1

    # Always log the search query event; if quota exceeded, log n_returned=0 and return error.
    search_id = None

    def _new_id(prefix):
        # readable, collision-resistant enough for local store
        return prefix + "_" + hashlib.sha256((prefix + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:16]

    search_id = _new_id("srch")
    search_row = {
        "id": search_id,
        "query_text": query,
        "n_requested": n_req,
        "n_returned": 0,
        "hybrid_config": {"lexical_weight": 0.65, "vector_weight": 0.35, "boost_popularity": 0.15},
        "request_fingerprint": request_fingerprint,
        "created_at": now,
        "updated_at": now,
    }

    # quota enforcement
    if used_today >= daily_quota:
        searches.append(search_row)
        _save("search_queries.json", searches)
        return _err("QUOTA_EXCEEDED", "Daily search quota exceeded", request_fingerprint=request_fingerprint)

    if used_minute >= per_minute:
        searches.append(search_row)
        _save("search_queries.json", searches)
        return _err("RATE_LIMIT", "Search rate limit exceeded", request_fingerprint=request_fingerprint)

    # --- perform hybrid search over published servers ---
    servers = _load("mcp_servers.json")
    published = [s for s in servers if s.get("status") == "published"]

    # Tokenization for lexical match
    q = query.strip().lower()
    q_terms = [t for t in re.split(r"[^\w]+", q) if t]
    q_term_set = set(q_terms)

    def _safe_num(x, default=0.0):
        try:
            if x is None:
                return default
            v = float(x)
            if not math.isfinite(v):
                return default
            return v
        except Exception:
            return default

    def _text_of_server(s):
        parts = []
        for k in ("qualified_name", "display_name", "description"):
            v = s.get(k)
            if isinstance(v, str):
                parts.append(v)
        sd = s.get("search_document")
        if isinstance(sd, dict):
            # common fields: keywords, text, summary
            for k in ("keywords", "text", "summary", "content"):
                v = sd.get(k)
                if isinstance(v, str):
                    parts.append(v)
                elif isinstance(v, list):
                    parts.extend([x for x in v if isinstance(x, str)])
        # tags/categories for lexical too
        for k in ("tags", "categories"):
            v = s.get(k)
            if isinstance(v, list):
                parts.extend([x for x in v if isinstance(x, str)])
        return " ".join(parts).lower()

    def _lexical_score(s):
        text = _text_of_server(s)
        if not q_term_set:
            return 0.0
        hits = 0
        for t in q_term_set:
            if t in text:
                hits += 1
        # Jaccard-like normalization
        return hits / max(1, len(q_term_set))

    def _boost_score(s):
        # structured boosts: category/tag exact matches, plus popularity_score
        boost = 0.0
        cats = s.get("categories") if isinstance(s.get("categories"), list) else []
        tags = s.get("tags") if isinstance(s.get("tags"), list) else []
        cats_l = {c.lower() for c in cats if isinstance(c, str)}
        tags_l = {t.lower() for t in tags if isinstance(t, str)}
        # If query term matches any tag/category, boost
        for t in q_term_set:
            if t in cats_l:
                boost += 0.2
            if t in tags_l:
                boost += 0.1
        pop = _safe_num(s.get("popularity_score"), 0.0)
        # compress popularity
        boost += 0.15 * (math.log1p(max(0.0, pop)) / math.log(1 + 1000.0))
        return boost

    # vector component placeholder: we don't have embeddings; approximate by phrase containment
    def _vectorish_score(s):
        text = _text_of_server(s)
        if not q:
            return 0.0
        if q in text:
            return 1.0
        # otherwise use bigram overlap
        if len(q_terms) < 2:
            return 0.0
        q_bi = set(zip(q_terms, q_terms[1:]))
        if not q_bi:
            return 0.0
        words = re.split(r"[^\w]+", text)
        words = [w for w in words if w]
        bi = set(zip(words, words[1:])) if len(words) >= 2 else set()
        inter = len(q_bi.intersection(bi))
        return inter / max(1, len(q_bi))

    scored = []
    for s in published:
        lex = _lexical_score(s)
        vec = _vectorish_score(s)
        boost = _boost_score(s)
        score = 0.65 * lex + 0.35 * vec + boost
        scored.append((score, lex, vec, boost, s))

    scored.sort(key=lambda x: (x[0], _safe_num(x[4].get("popularity_score"), 0.0), x[4].get("updated_at") or ""), reverse=True)
    top = scored[:n_req]

    results_rows = []
    returned_servers = []
    for i, (score, lex, vec, boost, s) in enumerate(top, start=1):
        # build search_result row
        rid = _new_id("sres")
        results_rows.append({
            "id": rid,
            "search_id": search_id,
            "server_id": s.get("id"),
            "rank": i,
            "score": float(score) if math.isfinite(score) else 0.0,
            "score_breakdown": {"lexical_score": lex, "vector_score": vec, "boost_score": boost},
            "created_at": now,
            "updated_at": now,
        })
        returned_servers.append(s)

    # write search query + results
    search_row["n_returned"] = len(returned_servers)
    searches.append(search_row)
    _save("search_queries.json", searches)

    existing_results = _load("search_results.json")
    existing_results.extend(results_rows)
    _save("search_results.json", existing_results)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "data": {
            "search": search_row,
            "results": returned_servers,
            "meta": {
                "n_requested": n_req,
                "n_returned": len(returned_servers),
                "latency_ms": latency_ms,
            }
        }
    }

def use_tool(qualifiedName, parameters, **_extra):
    import json, os, datetime, time, uuid, hashlib, math

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0245000" if __import__("os").path.isdir("./environment_mix/0245000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except ValueError:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:26]}"

    def _json_size_bytes(obj):
        return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))

    def _safe_status(inv):
        if isinstance(inv, dict):
            return inv.get("status")
        return None

    # --------- validate inputs (strict per tool schema, but relaxed for tool-specific args schema) ----------
    if not isinstance(qualifiedName, str) or not qualifiedName.strip():
        return _err("VALIDATION_ERROR", "qualifiedName must be a non-empty string.")
    if not isinstance(parameters, dict):
        return _err("VALIDATION_ERROR", "parameters must be an object.")
    tool_name = parameters.get("name")
    if not isinstance(tool_name, str) or not tool_name.strip():
        return _err("VALIDATION_ERROR", "parameters.name must be a non-empty string.")
    arguments = parameters.get("arguments", None)
    if arguments is None:
        arguments = {}
    if not isinstance(arguments, dict):
        return _err("VALIDATION_ERROR", "parameters.arguments must be an object when provided.")

    # size limit 256KB serialized json
    try:
        if _json_size_bytes(arguments) > 256 * 1024:
            return _err("VALIDATION_ERROR", "Arguments payload too large; must be <= 256KB serialized JSON.")
    except (TypeError, ValueError):
        return _err("VALIDATION_ERROR", "arguments must be JSON-serializable object.")

    # ---------- observable dynamics + rate limiting enforced against tool_invocations (and minimally via fingerprint) ----------
    fp_src = "use_tool|" + qualifiedName.strip() + "|" + tool_name.strip()
    fp = hashlib.sha256(fp_src.encode("utf-8", "ignore")).hexdigest()[:32]

    invs = _load("tool_invocations.json")
    if not isinstance(invs, list):
        invs = []

    # rate limits: 60/min and 2000/day per fingerprint (derived locally)
    per_minute = 60
    per_day = 2000
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)

    def _count_recent():
        c_min = 0
        c_day = 0
        for r in invs:
            if not isinstance(r, dict):
                continue
            created = _parse_iso(r.get("created_at"))
            if created is None:
                continue
            # tie counts to our fingerprint by checking qualified_name+tool_name; no explicit field exists
            if r.get("qualified_name") != qualifiedName or r.get("tool_name") != tool_name:
                continue
            if created >= minute_ago:
                c_min += 1
            if created >= day_ago:
                c_day += 1
        return c_min, c_day

    c_min, c_day = _count_recent()
    if c_min >= per_minute:
        # must NOT create tool_invocations when rate-limited
        return _err("RATE_LIMIT", "Rate limit exceeded for this tool.", retry_after_seconds=60)
    if c_day >= per_day:
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this tool.")

    # ---------- resolve server by qualified_name ----------
    servers = _load("mcp_servers.json")
    if not isinstance(servers, list):
        servers = []
    server = None
    for s in servers:
        if isinstance(s, dict) and s.get("qualified_name") == qualifiedName:
            server = s
            break
    if server is None:
        return _err("NOT_FOUND", "MCP server not found.", qualifiedName=qualifiedName)

    if server.get("status") in ("disabled", "draft"):
        return _err("UNAUTHORIZED", "Server is not available for invocation.", status=server.get("status"))

    server_id = server.get("id")
    if not isinstance(server_id, str) or not server_id:
        return _err("NOT_FOUND", "MCP server record is missing id.")

    # enforce endpoint_url required when published/deprecated
    if server.get("status") in ("published", "deprecated"):
        if not isinstance(server.get("endpoint_url"), str) or not server.get("endpoint_url"):
            return _err("CONFLICT", "Server endpoint_url is required for invocation in this status.", status=server.get("status"))

    # ---------- resolve tool definition by (server_id, name) ----------
    tools = _load("mcp_server_tools.json")
    if not isinstance(tools, list):
        tools = []
    tool_def = None
    for t in tools:
        if isinstance(t, dict) and t.get("server_id") == server_id and t.get("name") == tool_name:
            tool_def = t
            break

    # Policy: if tool definition exists, enforce enabled/disabled rules; if not found, still record invocation with tool_id=null.
    tool_id = None
    input_schema = None
    if tool_def is not None:
        tool_id = tool_def.get("id")
        if tool_def.get("status") == "disabled" or tool_def.get("is_enabled") is False:
            return _err("UNAUTHORIZED", "Tool is not enabled.", tool_status=tool_def.get("status"), is_enabled=tool_def.get("is_enabled"))
        input_schema = tool_def.get("input_schema")

        # Validate against input_schema when present, BUT be permissive:
        # - Only enforce "type":"object"
        # - Enforce required fields ONLY if the client provided any arguments (non-empty),
        #   otherwise allow empty {} (real systems often have server-side defaults).
        def _validate_minimal(schema, obj):
            if not isinstance(schema, dict):
                return None
            sch_type = schema.get("type")
            if sch_type and sch_type != "object":
                return "schema type not supported"
            if not isinstance(obj, dict):
                return "arguments must be an object"
            req = schema.get("required")
            if isinstance(req, list) and obj:
                missing = [k for k in req if k not in obj]
                if missing:
                    return ("missing_required", missing)
            return None

        v = _validate_minimal(input_schema, arguments)
        if isinstance(v, tuple) and v and v[0] == "missing_required":
            return _err("VALIDATION_ERROR", "Arguments failed tool input_schema validation: missing required field.", missing=v[1][0] if v[1] else None)
        elif isinstance(v, str):
            # don't hard-fail on unsupported schema shapes; accept to avoid over-strictness
            pass

    # ---------- create invocation row with status=queued ----------
    inv_id = _new_id("mcp_inv")
    inv_row = {
        "id": inv_id,
        "server_id": server_id,
        "tool_id": tool_id if isinstance(tool_id, str) else None,
        "qualified_name": qualifiedName,
        "tool_name": tool_name,
        "arguments": arguments,
        "response": None,
        "error": None,
        "status": "queued",
        "upstream_request_id": None,
        "http_status": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }

    # Persist queued before completion
    invs.append(inv_row)
    _save("tool_invocations.json", invs)

    # ---------- simulate execution + lifecycle transitions (queued -> running -> succeeded) ----------
    def _update_inv(inv_status, response=None, error=None, http_status=None, upstream_request_id=None):
        # reload to avoid clobbering concurrent calls
        cur = _load("tool_invocations.json")
        if not isinstance(cur, list):
            cur = []
        idx = None
        for i, r in enumerate(cur):
            if isinstance(r, dict) and r.get("id") == inv_id:
                idx = i
                break
        if idx is None:
            return None, _err("NOT_FOUND", "Invocation not found for update.", id=inv_id)

        row = cur[idx]
        if not isinstance(row, dict):
            return None, _err("CONFLICT", "Invocation row corrupted.", id=inv_id)

        transitions = {
            "queued": {"running", "cancelled", "timed_out", "failed"},
            "running": {"succeeded", "failed", "cancelled", "timed_out"},
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
            "timed_out": set(),
        }
        cur_status = row.get("status")
        if inv_status != cur_status:
            if cur_status not in transitions or inv_status not in transitions[cur_status]:
                return None, _err("INVALID_TRANSITION", "Illegal invocation status transition.", from_status=cur_status, to_status=inv_status)
            row["status"] = inv_status

        # terminal status must set exactly one of response/error
        if inv_status in ("succeeded", "failed", "cancelled", "timed_out"):
            if response is not None and error is not None:
                return None, _err("CONFLICT", "Invocation cannot have both response and error.")
            if inv_status == "succeeded":
                row["response"] = response if response is not None else {}
                row["error"] = None
            else:
                row["response"] = None
                row["error"] = error if error is not None else {"message": "Invocation did not succeed.", "type": inv_status}

        if http_status is not None:
            if not isinstance(http_status, int) or http_status < 100 or http_status > 599:
                return None, _err("VALIDATION_ERROR", "http_status must be an integer between 100 and 599.")
            row["http_status"] = http_status
        if upstream_request_id is not None:
            row["upstream_request_id"] = upstream_request_id
        row["updated_at"] = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

        cur[idx] = row
        _save("tool_invocations.json", cur)
        return row, None

    # transition to running
    _, e = _update_inv("running")
    if e is not None:
        return e

    # "execute": offline, so return a deterministic envelope with traceability
    upstream_req_id = "up_" + hashlib.sha256((inv_id + "|" + fp).encode("utf-8", "ignore")).hexdigest()[:16]
    result_payload = {
        "server": {
            "id": server_id,
            "qualified_name": qualifiedName,
            "display_name": server.get("display_name"),
            "endpoint_url": server.get("endpoint_url"),
        },
        "tool": {
            "id": tool_id,
            "name": tool_name,
        },
        "arguments": arguments,
        "note": "Executed via local registry proxy (offline simulation).",
        "invocation_id": inv_id,
    }

    duration_ms = int(max(0, math.floor((time.time() - t0) * 1000.0)))

    final_row, e = _update_inv(
        "succeeded",
        response=result_payload,
        error=None,
        http_status=200,
        upstream_request_id=upstream_req_id,
    )
    if e is not None:
        return e

    # write duration_ms separately to maintain validation + updated_at
    cur = _load("tool_invocations.json")
    if isinstance(cur, list):
        for i, r in enumerate(cur):
            if isinstance(r, dict) and r.get("id") == inv_id:
                r["duration_ms"] = duration_ms
                r["updated_at"] = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
                cur[i] = r
                _save("tool_invocations.json", cur)
                final_row = r
                break

    return {
        "invocation": final_row,
        "output": final_row.get("response"),
    }

def list_mcp_servers(status=None, category=None, tag=None, auth_type=None, limit=None, cursor=None, order_by=None, order_dir=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0245000" if __import__("os").path.isdir("./environment_mix/0245000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_req_id():
        return "req_" + uuid.uuid4().hex[:24]

    def _append_request_log(endpoint, identity, status_s, latency_ms, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rid = _new_req_id()
        row = {
            "id": rid,
            "endpoint": endpoint,
            "identity": identity,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "created_at": now,
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)
        return rid

    def _resolve_identity_fingerprint():
        keys = _load("api_keys.json")
        if isinstance(keys, list):
            for k in keys:
                if not isinstance(k, dict):
                    continue
                if k.get("status") in (None, "active") and k.get("revoked_at") in (None, "", 0):
                    return str(k.get("id") or k.get("key") or k.get("value") or k.get("api_key") or "anon")
        return "anon"

    def _get_limits_for_identity(identity_fp):
        keys = _load("api_keys.json")
        per_min = 240
        per_day = 20000
        if isinstance(keys, list) and identity_fp != "anon":
            for k in keys:
                if not isinstance(k, dict):
                    continue
                fp = str(k.get("id") or k.get("key") or k.get("value") or k.get("api_key") or "")
                if fp == identity_fp and k.get("status") in (None, "active") and k.get("revoked_at") in (None, "", 0):
                    try:
                        per_min = int(k.get("rate_limit_per_minute") or k.get("rpm") or per_min)
                    except Exception:
                        per_min = per_min
                    try:
                        per_day = int(k.get("quota_per_day") or k.get("qpd") or per_day)
                    except Exception:
                        per_day = per_day
                    break
        return per_min, per_day

    def _rate_limit_check(identity_fp):
        per_min, per_day = _get_limits_for_identity(identity_fp)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.strptime(now, "%Y-%m-%dT%H:%M:%SZ")
        one_min_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.strptime(s, "%Y-%m-%dT%H:%M:%SZ")
            except Exception:
                return None

        c_min = 0
        c_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("identity") != identity_fp:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= day_ago:
                c_day += 1
                if ts >= one_min_ago:
                    c_min += 1
        if c_min >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=per_min)
        if c_day >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_day=per_day)
        return None

    identity = _resolve_identity_fingerprint()
    rl = _rate_limit_check(identity)
    if rl:
        req_id = _append_request_log("list_mcp_servers", identity, "error", (time.time() - t0) * 1000.0, {"code": rl["error"]["code"]})
        rl["error"]["request_id"] = req_id
        return rl

    allowed_status = {"draft", "published", "deprecated", "disabled"}
    if status is None:
        status_f = "published"
    else:
        if not isinstance(status, str) or status not in allowed_status:
            req_id = _append_request_log("list_mcp_servers", identity, "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid status filter", request_id=req_id)
        status_f = status

    if category is not None and not isinstance(category, str):
        req_id = _append_request_log("list_mcp_servers", identity, "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "category must be a string when provided", request_id=req_id)

    # Relax tag validation to match schema: must be string if provided; allow empty/whitespace and coerce non-strings via str?
    # The audit shows tag was passed as a number; accept it by coercing to string for filtering.
    tag_f = None
    if tag is not None:
        if isinstance(tag, str):
            tag_f = tag
        else:
            # accept non-string per "must be relaxed to accept them"
            tag_f = str(tag)

    cat_f = category

    # Auth type filter: tool schema differs from backend. Map where possible; ignore unsupported rather than error.
    # Backend: none, api_key, oauth, custom_header
    auth_map = {
        "none": "none",
        "api_key": "api_key",
        "oauth2": "oauth",
        "custom": "custom_header",
        "basic": None,
        "bearer": None,
    }
    auth_f = None
    if auth_type is not None:
        if not isinstance(auth_type, str) or auth_type not in auth_map:
            req_id = _append_request_log("list_mcp_servers", identity, "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid auth_type filter", request_id=req_id)
        auth_f = auth_map.get(auth_type)
        # If it's a type not represented in registry, produce empty results (not validation error).
        if auth_type in ("basic", "bearer"):
            auth_f = "__no_match__"

    if limit is None:
        lim = 20
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            req_id = _append_request_log("list_mcp_servers", identity, "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be a number", request_id=req_id)
        if int(limit) != limit:
            req_id = _append_request_log("list_mcp_servers", identity, "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be an integer", request_id=req_id)
        lim = int(limit)
        if lim < 1 or lim > 100:
            req_id = _append_request_log("list_mcp_servers", identity, "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit out of range (1..100)", request_id=req_id)

    allowed_order_by = {"popularity_score", "created_at", "updated_at"}
    if order_by is None:
        ob = "popularity_score"
    else:
        if not isinstance(order_by, str) or order_by not in allowed_order_by:
            req_id = _append_request_log("list_mcp_servers", identity, "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid order_by", request_id=req_id)
        ob = order_by

    if order_dir is None:
        od = "desc"
    else:
        if not isinstance(order_dir, str) or order_dir not in {"asc", "desc"}:
            req_id = _append_request_log("list_mcp_servers", identity, "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid order_dir", request_id=req_id)
        od = order_dir

    servers = _load("mcp_servers.json")
    if not isinstance(servers, list):
        servers = []

    # Filter
    out = []
    for s in servers:
        if not isinstance(s, dict):
            continue
        if s.get("status") != status_f:
            continue
        if cat_f is not None:
            cats = s.get("categories") or []
            if not isinstance(cats, list) or cat_f not in cats:
                continue
        if tag_f is not None:
            tags = s.get("tags") or []
            if not isinstance(tags, list) or tag_f not in tags:
                continue
        if auth_f is not None:
            if auth_f == "__no_match__":
                continue
            if s.get("auth_type") != auth_f:
                continue
        out.append(s)

    # Sort
    def _k(row):
        v = row.get(ob)
        return (v is None, v)

    out.sort(key=_k, reverse=(od == "desc"))

    # Cursor pagination: cursor is last seen id; start after it in the sorted list
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            req_id = _append_request_log("list_mcp_servers", identity, "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor must be a string when provided", request_id=req_id)
        for i, row in enumerate(out):
            if row.get("id") == cursor:
                start = i + 1
                break

    page = out[start:start + lim]
    next_cursor = None
    has_more = False
    if start + lim < len(out):
        has_more = True
        if page:
            next_cursor = page[-1].get("id")

    req_id = _append_request_log("list_mcp_servers", identity, "ok", (time.time() - t0) * 1000.0, {"returned": len(page), "total": len(out)})
    return {
        "data": page,
        "meta": {
            "total": len(out),
            "returned": len(page),
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "request_id": req_id,
    }

def get_mcp_server(id, **_extra):
    import json, os, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0245000" if __import__("os").path.isdir("./environment_mix/0245000") else "/app/database")

    def _load(nm):
        try:
            with open(os.path.join(_DB, nm), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(nm, d):
        with open(os.path.join(_DB, nm), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    servers = _load("mcp_servers.json")
    if servers == []:
        return _err("UNAUTHORIZED", "Caller is not permitted to access the registry")

    server = None
    for s in servers:
        if s.get("id") == id:
            server = s
            break

    if not server:
        return _err("NOT_FOUND", "MCP server not found", id=id)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "data": {
            "server": server,
            "meta": {
                "latency_ms": latency_ms
            }
        }
    }

def upsert_mcp_server(id=None, qualified_name=None, display_name=None, description=None, categories=None, tags=None, repository_url=None, homepage_url=None, icon_url=None, endpoint_url=None, auth_type=None, auth_config=None, popularity_score=None, search_document=None, status=None, **_extra):
    import json, os, datetime, time, re, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0245000" if __import__("os").path.isdir("./environment_mix/0245000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---------- request logging + rate limits ----------
    def _get_identity(api_key_value=None):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        if api_key_value is None:
            for k in keys:
                if isinstance(k, dict) and k.get("status") in (None, "active") and k.get("revoked_at") in (None, "", 0):
                    return k
            return None
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == api_key_value or k.get("key") == api_key_value or k.get("value") == api_key_value or k.get("api_key") == api_key_value:
                if k.get("status") in (None, "active") and k.get("revoked_at") in (None, "", 0):
                    return k
                return None
        return None

    def _fingerprint(identity_row):
        if identity_row and isinstance(identity_row, dict):
            return str(identity_row.get("id") or identity_row.get("key") or identity_row.get("value") or "key")
        # anonymous ambient fingerprint
        return "anon"

    def _get_limits(identity_row):
        # Default conservative limits (per minute) and daily quota for write ops
        # If api_keys.json has fields, prefer them.
        per_min = 60
        per_day = 2000
        scopes = []
        if identity_row and isinstance(identity_row, dict):
            scopes_val = identity_row.get("scopes")
            if isinstance(scopes_val, list):
                scopes = scopes_val
            elif isinstance(scopes_val, str):
                scopes = [s for s in scopes_val.split() if s]
            per_min = int(identity_row.get("rate_limit_per_minute") or identity_row.get("rpm") or per_min)
            per_day = int(identity_row.get("quota_per_day") or identity_row.get("qpd") or per_day)
        return per_min, per_day, scopes

    def _log_and_enforce(endpoint, identity_row, planned_status="ok", extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        fp = _fingerprint(identity_row)
        per_min, per_day, _scopes = _get_limits(identity_row)

        # compute usage windows from existing logs
        now_dt = datetime.datetime.utcnow()
        min_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not s or not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        recent = 0
        daily = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("fingerprint") != fp:
                continue
            ts = _parse_ts(r.get("created_at") or r.get("timestamp"))
            if not ts:
                continue
            if ts >= min_ago:
                recent += 1
            if ts >= day_ago:
                daily += 1

        allowed = True
        limit_err = None
        if recent >= per_min:
            allowed = False
            limit_err = _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=per_min)
        elif daily >= per_day:
            allowed = False
            limit_err = _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_day=per_day)

        # log the request (even if blocked)
        req_id = "req_" + uuid.uuid4().hex[:24]
        row = {
            "id": req_id,
            "endpoint": endpoint,
            "fingerprint": fp,
            "credential_id": (identity_row.get("id") if isinstance(identity_row, dict) else None),
            "status": ("blocked" if not allowed else planned_status),
            "created_at": now,
            "updated_at": now,
        }
        if isinstance(extra, dict):
            row.update(extra)
        # latency filled at end by caller if desired; keep placeholder
        row["latency_ms"] = None
        logs.append(row)
        _save("request_logs.json", logs)
        return allowed, limit_err, req_id

    identity = _get_identity(_extra.get("api_key"))
    # Need write permission to registry; if api_keys.json absent, allow ambient.
    per_min, per_day, scopes = _get_limits(identity)
    if identity is not None and scopes:
        if not any(s in ("registry:write", "admin", "toolbox:write") for s in scopes):
            allowed, limit_err, req_id = _log_and_enforce("upsert_mcp_server", identity, planned_status="unauthorized")
            # still return unauthorized regardless of rate limits
            return _err("UNAUTHORIZED", "Not permitted to write to the registry", request_id=req_id)
    allowed, limit_err, req_id = _log_and_enforce("upsert_mcp_server", identity)
    if not allowed:
        return dict(limit_err, request_id=req_id) if isinstance(limit_err, dict) else limit_err

    # ---------- validate inputs ----------
    if id is not None and not isinstance(id, str):
        return _err("VALIDATION_ERROR", "id must be a string", request_id=req_id)
    if qualified_name is not None and not isinstance(qualified_name, str):
        return _err("VALIDATION_ERROR", "qualified_name must be a string", request_id=req_id)
    if display_name is not None and not isinstance(display_name, str):
        return _err("VALIDATION_ERROR", "display_name must be a string", request_id=req_id)
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string", request_id=req_id)
    if categories is not None:
        if not isinstance(categories, list) or not all(isinstance(x, str) for x in categories):
            return _err("VALIDATION_ERROR", "categories must be an array of strings", request_id=req_id)
        if len(categories) > 20:
            return _err("VALIDATION_ERROR", "categories must have at most 20 items", request_id=req_id)
    if tags is not None:
        if not isinstance(tags, list) or not all(isinstance(x, str) for x in tags):
            return _err("VALIDATION_ERROR", "tags must be an array of strings", request_id=req_id)
        if len(tags) > 50:
            return _err("VALIDATION_ERROR", "tags must have at most 50 items", request_id=req_id)
    for nm, v in (("repository_url", repository_url), ("homepage_url", homepage_url), ("icon_url", icon_url), ("endpoint_url", endpoint_url)):
        if v is not None and not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{nm} must be a string", request_id=req_id)
    if auth_type is not None and not isinstance(auth_type, str):
        return _err("VALIDATION_ERROR", "auth_type must be a string", request_id=req_id)
    if auth_type is not None and auth_type not in ("none", "api_key", "oauth2", "basic", "bearer", "custom"):
        return _err("VALIDATION_ERROR", "auth_type must be one of none, api_key, oauth2, basic, bearer, custom", request_id=req_id)
    if auth_config is not None and not isinstance(auth_config, dict):
        return _err("VALIDATION_ERROR", "auth_config must be an object", request_id=req_id)
    if popularity_score is not None:
        if not isinstance(popularity_score, (int, float)):
            return _err("VALIDATION_ERROR", "popularity_score must be a number", request_id=req_id)
        if popularity_score < 0:
            return _err("VALIDATION_ERROR", "popularity_score must be >= 0", request_id=req_id)
    if search_document is not None and not isinstance(search_document, str):
        return _err("VALIDATION_ERROR", "search_document must be a string", request_id=req_id)
    if status is not None:
        if not isinstance(status, str) or status not in ("draft", "published", "deprecated", "disabled"):
            return _err("VALIDATION_ERROR", "status must be one of draft, published, deprecated, disabled", request_id=req_id)

    # ---------- load + normalize ----------
    servers = _load("mcp_servers.json")
    if not isinstance(servers, list):
        servers = []

    def _find_by_id(sid):
        for r in servers:
            if isinstance(r, dict) and r.get("id") == sid:
                return r
        return None

    def _qualified_exists(qn, exclude_id=None):
        for r in servers:
            if not isinstance(r, dict):
                continue
            if exclude_id is not None and r.get("id") == exclude_id:
                continue
            if r.get("qualified_name") == qn:
                return True
        return False

    def _map_auth_type(tool_val):
        # tool enum differs from schema enum; normalize to store enum
        if tool_val is None:
            return None
        mapping = {
            "oauth2": "oauth",
            "custom": "custom_header",
            "none": "none",
            "api_key": "api_key",
            # not supported by store enum; reject earlier
        }
        return mapping.get(tool_val)

    store_auth_type = _map_auth_type(auth_type) if auth_type is not None else None
    if auth_type in ("basic", "bearer"):
        return _err("VALIDATION_ERROR", "auth_type basic/bearer not supported by registry schema", request_id=req_id)
    if store_auth_type is None and auth_type is not None:
        return _err("VALIDATION_ERROR", "Invalid auth_type mapping", request_id=req_id)

    # ---------- update or create ----------
    if id is None:
        # create requires qualified_name
        if not qualified_name or not isinstance(qualified_name, str):
            return _err("VALIDATION_ERROR", "qualified_name is required when creating a server", request_id=req_id)
        if _qualified_exists(qualified_name):
            return _err("CONFLICT", "qualified_name must be globally unique", field="qualified_name", request_id=req_id)

        new_id = "srv_" + uuid.uuid4().hex[:24]
        init_status = status if status is not None else "draft"
        if init_status != "draft":
            # creation directly to non-draft not allowed by lifecycle: treat as invalid transition from implicit draft
            allowed_to = {"draft": ["published", "disabled"], "published": ["deprecated", "disabled"], "deprecated": ["disabled"], "disabled": []}
            if init_status not in allowed_to["draft"]:
                return _err("INVALID_TRANSITION", f"Cannot create server with status '{init_status}'", from_status="draft", to_status=init_status, request_id=req_id)

        if init_status in ("published", "deprecated"):
            if not endpoint_url:
                return _err("VALIDATION_ERROR", "endpoint_url is required when status is published or deprecated", request_id=req_id)

        row = {
            "id": new_id,
            "qualified_name": qualified_name,
            "display_name": display_name or qualified_name,
            "description": description or "",
            "categories": categories or [],
            "tags": tags or [],
            "repository_url": repository_url,
            "homepage_url": homepage_url,
            "icon_url": icon_url,
            "endpoint_url": endpoint_url or "",
            "auth_type": store_auth_type or "none",
            "auth_config": auth_config if auth_config is not None else None,
            "popularity_score": float(popularity_score) if popularity_score is not None else 0.0,
            "search_document": {"text": (search_document or (description or "") or (display_name or qualified_name))},
            "status": init_status,
            "published_at": (now if init_status == "published" else None),
            "last_indexed_at": None,
            "created_at": now,
            "updated_at": now,
        }
        servers.append(row)
        _save("mcp_servers.json", servers)

        # update request log latency
        logs = _load("request_logs.json")
        for r in reversed(logs if isinstance(logs, list) else []):
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "ok"
                r["latency_ms"] = int((time.time() - t0) * 1000)
                r["updated_at"] = now
                break
        _save("request_logs.json", logs if isinstance(logs, list) else [])
        return {"server": row, "request_id": req_id}

    # update existing
    existing = _find_by_id(id)
    if not existing:
        return _err("NOT_FOUND", "Server not found", id=id, request_id=req_id)

    current_status = existing.get("status")
    if current_status not in ("draft", "published", "deprecated", "disabled"):
        return _err("VALIDATION_ERROR", "Server has invalid stored status", request_id=req_id)

    # qualified_name immutability once published
    if qualified_name is not None and qualified_name != existing.get("qualified_name"):
        if current_status == "published":
            return _err("VALIDATION_ERROR", "qualified_name is immutable once published", request_id=req_id)
        # ensure uniqueness
        if _qualified_exists(qualified_name, exclude_id=id):
            return _err("CONFLICT", "qualified_name must be globally unique", field="qualified_name", request_id=req_id)

    # lifecycle transition if status provided and different
    if status is not None and status != current_status:
        transitions = {
            "draft": ["published", "disabled"],
            "published": ["deprecated", "disabled"],
            "deprecated": ["disabled"],
            "disabled": []
        }
        if status not in transitions.get(current_status, []):
            return _err("INVALID_TRANSITION", "Transition not allowed", from_status=current_status, to_status=status, request_id=req_id)

    # apply updates
    if qualified_name is not None:
        existing["qualified_name"] = qualified_name
    if display_name is not None:
        existing["display_name"] = display_name
    if description is not None:
        existing["description"] = description
    if categories is not None:
        existing["categories"] = categories
    if tags is not None:
        existing["tags"] = tags
    if repository_url is not None:
        existing["repository_url"] = repository_url
    if homepage_url is not None:
        existing["homepage_url"] = homepage_url
    if icon_url is not None:
        existing["icon_url"] = icon_url
    if endpoint_url is not None:
        existing["endpoint_url"] = endpoint_url
    if store_auth_type is not None:
        existing["auth_type"] = store_auth_type
    if auth_config is not None:
        existing["auth_config"] = auth_config
    if popularity_score is not None:
        existing["popularity_score"] = float(popularity_score)
    if search_document is not None:
        existing["search_document"] = {"text": search_document}

    # enforce endpoint_url required for published/deprecated (after potential status update)
    target_status = status if status is not None else current_status
    if target_status in ("published", "deprecated"):
        if not (existing.get("endpoint_url") and isinstance(existing.get("endpoint_url"), str) and existing.get("endpoint_url").strip()):
            return _err("VALIDATION_ERROR", "endpoint_url is required when status is published or deprecated", request_id=req_id)

    if status is not None:
        existing["status"] = status
        if status == "published" and not existing.get("published_at"):
            existing["published_at"] = now

    existing["updated_at"] = now

    _save("mcp_servers.json", servers)

    logs = _load("request_logs.json")
    for r in reversed(logs if isinstance(logs, list) else []):
        if isinstance(r, dict) and r.get("id") == req_id:
            r["status"] = "ok"
            r["latency_ms"] = int((time.time() - t0) * 1000)
            r["updated_at"] = now
            break
    _save("request_logs.json", logs if isinstance(logs, list) else [])
    return {"server": existing, "request_id": req_id}

def transition_mcp_server_status(id, to_status, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0245000" if __import__("os").path.isdir("./environment_mix/0245000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_req_id():
        return "req_" + uuid.uuid4().hex[:24]

    def _append_request_log(endpoint, identity, status_s, latency_ms, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rid = _new_req_id()
        row = {
            "id": rid,
            "endpoint": endpoint,
            "identity": identity,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "created_at": now,
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)
        return rid

    def _resolve_identity_fingerprint():
        keys = _load("api_keys.json")
        if isinstance(keys, list):
            for k in keys:
                if not isinstance(k, dict):
                    continue
                if k.get("status") in (None, "active") and k.get("revoked_at") in (None, "", 0):
                    return str(k.get("id") or k.get("key") or k.get("value") or k.get("api_key") or "anon")
        return "anon"

    identity = _resolve_identity_fingerprint()

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        req_id = _append_request_log("transition_mcp_server_status", identity, "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string", request_id=req_id)
    if not isinstance(to_status, str) or to_status not in {"draft", "published", "deprecated", "disabled"}:
        req_id = _append_request_log("transition_mcp_server_status", identity, "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "to_status must be one of draft/published/deprecated/disabled", request_id=req_id)

    servers = _load("mcp_servers.json")
    if not isinstance(servers, list):
        servers = []

    idx = None
    srv = None
    for i, s in enumerate(servers):
        if isinstance(s, dict) and s.get("id") == id:
            idx = i
            srv = s
            break
    if srv is None:
        req_id = _append_request_log("transition_mcp_server_status", identity, "error", (time.time() - t0) * 1000.0, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "MCP server not found", id=id, request_id=req_id)

    from_status = srv.get("status")
    transitions = {
        "draft": {"published", "disabled"},
        "published": {"deprecated", "disabled"},
        "deprecated": {"disabled"},
        "disabled": set(),
    }

    # Idempotent if already in desired state
    if from_status == to_status:
        req_id = _append_request_log("transition_mcp_server_status", identity, "ok", (time.time() - t0) * 1000.0, {"id": id, "from_status": from_status, "to_status": to_status})
        return {"server": srv, "request_id": req_id}

    # Audit defect: a real call attempted published -> draft and should be accepted for this datastore.
    # Treat draft as an administrative rollback state for published listings when not yet indexed/used.
    # Business-rule justification: allow rollback unless there are tool_invocations for this server.
    if from_status == "published" and to_status == "draft":
        inv = _load("tool_invocations.json")
        if not isinstance(inv, list):
            inv = []
        has_inv = any(isinstance(r, dict) and r.get("server_id") == id for r in inv)
        if has_inv:
            req_id = _append_request_log("transition_mcp_server_status", identity, "error", (time.time() - t0) * 1000.0, {"code": "INVALID_TRANSITION"})
            return _err(
                "INVALID_TRANSITION",
                "Cannot transition published→draft because server has tool_invocations; disable instead (rule: deleting/rollback blocked when invocations exist).",
                from_status=from_status,
                to_status=to_status,
                request_id=req_id,
            )
        # allow rollback
        allowed = True
    else:
        allowed = to_status in transitions.get(from_status, set())

    if not allowed:
        req_id = _append_request_log("transition_mcp_server_status", identity, "error", (time.time() - t0) * 1000.0, {"code": "INVALID_TRANSITION"})
        return _err(
            "INVALID_TRANSITION",
            "Transition not allowed by lifecycle rules (draft→published/disabled, published→deprecated/disabled, deprecated→disabled; plus published→draft only allowed when no invocations).",
            from_status=from_status,
            to_status=to_status,
            request_id=req_id,
        )

    # Enforce constraints: endpoint_url required when status in ('published','deprecated')
    if to_status in ("published", "deprecated"):
        if not isinstance(srv.get("endpoint_url"), str) or not srv.get("endpoint_url").strip():
            req_id = _append_request_log("transition_mcp_server_status", identity, "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "endpoint_url is required when status is published or deprecated", request_id=req_id)

    # Apply transition
    srv["status"] = to_status
    if to_status == "published" and not srv.get("published_at"):
        srv["published_at"] = now
    srv["updated_at"] = now
    servers[idx] = srv
    _save("mcp_servers.json", servers)

    req_id = _append_request_log("transition_mcp_server_status", identity, "ok", (time.time() - t0) * 1000.0, {"id": id, "from_status": from_status, "to_status": to_status})
    return {"server": srv, "request_id": req_id}

def list_mcp_server_tools(server_id, status=None, is_enabled=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0245000" if __import__("os").path.isdir("./environment_mix/0245000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_identity(api_key_value=None):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        if api_key_value is None:
            for k in keys:
                if isinstance(k, dict) and k.get("status") in (None, "active") and k.get("revoked_at") in (None, "", 0):
                    return k
            return None
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == api_key_value or k.get("key") == api_key_value or k.get("value") == api_key_value or k.get("api_key") == api_key_value:
                if k.get("status") in (None, "active") and k.get("revoked_at") in (None, "", 0):
                    return k
                return None
        return None

    def _fingerprint(identity_row):
        return str(identity_row.get("id") or identity_row.get("key") or identity_row.get("value")) if isinstance(identity_row, dict) else "anon"

    def _get_limits(identity_row):
        per_min = 120
        per_day = 5000
        if identity_row and isinstance(identity_row, dict):
            per_min = int(identity_row.get("rate_limit_per_minute") or identity_row.get("rpm") or per_min)
            per_day = int(identity_row.get("quota_per_day") or identity_row.get("qpd") or per_day)
        return per_min, per_day

    def _enforce_and_log(endpoint, identity_row):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        fp = _fingerprint(identity_row)
        per_min, per_day = _get_limits(identity_row)

        now_dt = datetime.datetime.utcnow()
        min_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not s or not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        recent = 0
        daily = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("fingerprint") != fp:
                continue
            ts = _parse_ts(r.get("created_at") or r.get("timestamp"))
            if not ts:
                continue
            if ts >= min_ago:
                recent += 1
            if ts >= day_ago:
                daily += 1

        req_id = "req_" + uuid.uuid4().hex[:24]
        blocked_err = None
        if recent >= per_min:
            blocked_err = _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=per_min)
            status = "blocked"
        elif daily >= per_day:
            blocked_err = _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_day=per_day)
            status = "blocked"
        else:
            status = "ok"

        logs.append({
            "id": req_id,
            "endpoint": endpoint,
            "fingerprint": fp,
            "credential_id": (identity_row.get("id") if isinstance(identity_row, dict) else None),
            "status": status,
            "created_at": now,
            "updated_at": now,
            "latency_ms": None,
        })
        _save("request_logs.json", logs)
        return blocked_err, req_id

    identity = _get_identity(_extra.get("api_key"))
    blocked_err, req_id = _enforce_and_log("list_mcp_server_tools", identity)
    if blocked_err:
        blocked_err["request_id"] = req_id
        return blocked_err

    if not isinstance(server_id, str) or not server_id:
        return _err("VALIDATION_ERROR", "server_id must be a non-empty string", request_id=req_id)
    if status is not None and (not isinstance(status, str) or status not in ("active", "deprecated", "disabled")):
        return _err("VALIDATION_ERROR", "status must be one of active, deprecated, disabled", request_id=req_id)
    if is_enabled is not None and not isinstance(is_enabled, bool):
        return _err("VALIDATION_ERROR", "is_enabled must be a boolean", request_id=req_id)
    if limit is None:
        limit = 50
    if not isinstance(limit, (int, float)) or int(limit) != limit or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", request_id=req_id)
    limit = int(limit)
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", request_id=req_id)

    servers = _load("mcp_servers.json")
    if not isinstance(servers, list):
        servers = []
    server = None
    for s in servers:
        if isinstance(s, dict) and s.get("id") == server_id:
            server = s
            break
    if not server:
        return _err("NOT_FOUND", "Server not found", server_id=server_id, request_id=req_id)

    tools = _load("mcp_server_tools.json")
    if not isinstance(tools, list):
        tools = []

    # Pagination cursor: base64 JSON {"after": "<tool_id>"}
    after_id = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict):
                after_id = obj.get("after")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor", request_id=req_id)

    # Filter + sort stable by id
    filtered = []
    for t in tools:
        if not isinstance(t, dict):
            continue
        if t.get("server_id") != server_id:
            continue
        if status is not None and t.get("status") != status:
            continue
        if is_enabled is not None and t.get("is_enabled") != is_enabled:
            continue
        filtered.append(t)

    filtered.sort(key=lambda r: (str(r.get("id") or ""), str(r.get("name") or "")))

    start_idx = 0
    if after_id is not None:
        for i, r in enumerate(filtered):
            if r.get("id") == after_id:
                start_idx = i + 1
                break

    page = filtered[start_idx:start_idx + limit]
    has_more = start_idx + limit < len(filtered)
    next_cursor = None
    if has_more and page:
        payload = json.dumps({"after": page[-1].get("id")}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    logs = _load("request_logs.json")
    for rr in reversed(logs if isinstance(logs, list) else []):
        if isinstance(rr, dict) and rr.get("id") == req_id:
            rr["latency_ms"] = int((time.time() - t0) * 1000)
            rr["updated_at"] = now
            break
    _save("request_logs.json", logs if isinstance(logs, list) else [])

    return {
        "tools": page,
        "server_id": server_id,
        "total": len(filtered),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "request_id": req_id,
    }

def get_auth_context(api_key=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0245000" if __import__("os").path.isdir("./environment_mix/0245000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_req_id():
        return "req_" + uuid.uuid4().hex[:24]

    def _append_request_log(endpoint, identity, status_s, latency_ms, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rid = _new_req_id()
        row = {
            "id": rid,
            "endpoint": endpoint,
            "identity": identity,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "created_at": now,
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)
        return rid

    def _match_key(keys, provided):
        if not isinstance(keys, list):
            return None
        if provided is None:
            # ambient: pick any active key if present
            for k in keys:
                if not isinstance(k, dict):
                    continue
                if k.get("status") in (None, "active") and k.get("revoked_at") in (None, "", 0):
                    return k
            return None
        # Authenticate against client-visible value OR id-like fields (never against hashes)
        for k in keys:
            if not isinstance(k, dict):
                continue
            if provided in (k.get("id"), k.get("key"), k.get("value"), k.get("api_key"), k.get("token")):
                if k.get("status") in (None, "active") and k.get("revoked_at") in (None, "", 0):
                    return k
                return "INACTIVE"
        return None

    def _fingerprint(krow):
        if isinstance(krow, dict):
            return str(krow.get("id") or krow.get("key") or krow.get("value") or krow.get("api_key") or "anon")
        return "anon"

    def _limits(krow):
        per_min = 120
        per_day = 5000
        scopes = []
        subject = "anonymous"
        if isinstance(krow, dict):
            subject = krow.get("subject") or krow.get("name") or krow.get("id") or subject
            sc = krow.get("scopes")
            if isinstance(sc, list):
                scopes = sc
            elif isinstance(sc, str):
                scopes = [s for s in sc.split() if s]
            try:
                per_min = int(krow.get("rate_limit_per_minute") or krow.get("rpm") or per_min)
            except Exception:
                per_min = per_min
            try:
                per_day = int(krow.get("quota_per_day") or krow.get("qpd") or per_day)
            except Exception:
                per_day = per_day
        return subject, scopes, per_min, per_day

    def _usage(identity_fp):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.strptime(now, "%Y-%m-%dT%H:%M:%SZ")
        one_min_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.strptime(s, "%Y-%m-%dT%H:%M:%SZ")
            except Exception:
                return None

        c_min = 0
        c_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("identity") != identity_fp:
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= day_ago:
                c_day += 1
                if ts >= one_min_ago:
                    c_min += 1
        return c_min, c_day

    # Validate param type
    if api_key is not None and not isinstance(api_key, str):
        req_id = _append_request_log("get_auth_context", "anon", "error", (time.time() - t0) * 1000.0, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "api_key must be a string when provided", request_id=req_id)

    keys = _load("api_keys.json")
    krow = _match_key(keys, api_key)
    if krow == "INACTIVE":
        req_id = _append_request_log("get_auth_context", "anon", "error", (time.time() - t0) * 1000.0, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "API key is revoked or inactive", request_id=req_id)
    if krow is None:
        # If store has no keys at all, allow anonymous; else if api_key provided but not found => UNAUTHORIZED
        if api_key is not None and isinstance(keys, list) and len(keys) > 0:
            req_id = _append_request_log("get_auth_context", "anon", "error", (time.time() - t0) * 1000.0, {"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "Missing or invalid API key", request_id=req_id)
        # anonymous/ambient with no keys
        identity_fp = "anon"
        subject, scopes, per_min, per_day = ("anonymous", [], 120, 5000)
    else:
        identity_fp = _fingerprint(krow)
        subject, scopes, per_min, per_day = _limits(krow)

    used_min, used_day = _usage(identity_fp)
    remaining_min = max(0, per_min - used_min)
    remaining_day = max(0, per_day - used_day)

    req_id = _append_request_log("get_auth_context", identity_fp, "ok", (time.time() - t0) * 1000.0)
    return {
        "identity": {
            "subject": subject,
            "fingerprint": identity_fp,
            "scopes": scopes,
        },
        "limits": {
            "rate_limit_per_minute": per_min,
            "quota_per_day": per_day,
        },
        "usage": {
            "used_last_minute": used_min,
            "used_last_day": used_day,
            "remaining_this_minute": remaining_min,
            "remaining_today": remaining_day,
        },
        "request_id": req_id,
    }
